(4152894, 595542, 80976, '<td valign="top">I think this would benefit from a perspective change, it feels almost like he''s falling out of the picture.</td>', 'I think this would benefit from a perspective change, it feels almost like he''s falling out of the picture.', '2007-10-08 21:42:33.000000', NULL, 1),
(4152900, 596567, 80976, '<td valign="top">Very nice, top 10 material for sure.</td>', 'Very nice, top 10 material for sure.', '2007-10-08 21:45:24.000000', NULL, 1),
