(4153024, 596921, 80976, '<td valign="top">Great detail, nice smooth reflection.</td>', 'Great detail, nice smooth reflection.', '2007-10-08 22:28:17.000000', NULL, 1),
(4153028, 597022, 80976, '<td valign="top">Good Macro but it feels very shoehorned for the challenge.  I''m not a big fan of the border either.</td>', 'Good Macro but it feels very shoehorned for the challenge.  I''m not a big fan of the border either.', '2007-10-08 22:29:11.000000', NULL, 1),
(4153034, 596463, 80976, '<td valign="top">The perspective is very creative, good job.</td>', 'The perspective is very creative, good job.', '2007-10-08 22:30:30.000000', NULL, 1),
(4153051, 596777, 80976, '<td valign="top">The imbalanced composition is throwing me off.  If you were more squared to the path and dropped some of the bottome of the image it would help a lot.</td>', 'The imbalanced composition is throwing me off.  If you were more squared to the path and dropped some of the bottome of the image it would help a lot.', '2007-10-08 22:34:04.000000', NULL, 1),
