(4153069, 597009, 80976, '<td valign="top">haha love the idea and great composition. It''s too bad the light is only hitting the left half of the cat''s face.</td>', 'haha love the idea and great composition. It''s too bad the light is only hitting the left half of the cat''s face.', '2007-10-08 22:36:49.000000', NULL, 1),
(4153079, 595806, 80976, '<td valign="top">Nice cap, the heavy shadows take away a lot of the detail in the surroundings.</td>', 'Nice cap, the heavy shadows take away a lot of the detail in the surroundings.', '2007-10-08 22:38:36.000000', NULL, 1),
(4153081, 596671, 80976, '<td valign="top">Very creative, amazing DOF.  Nicely done.</td>', 'Very creative, amazing DOF.  Nicely done.', '2007-10-08 22:39:11.000000', NULL, 1),
