INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4153238, 596958, 83313, '<td valign="top">Pretty grim, but it does make it''s point quite clearly. A very stark image.</td>', 'Pretty grim, but it does make it''s point quite clearly. A very stark image.', '2007-10-08 23:26:24.000000', NULL, 1),
(4153239, 596903, 80976, '<td valign="top">Wow amazing macro shot.  Without the name the tie to the challange is loose, but amazing pic none the less.</td>', 'Wow amazing macro shot.  Without the name the tie to the challange is loose, but amazing pic none the less.', '2007-10-08 23:27:02.000000', NULL, 1),
(4153240, 596189, 83313, '<td valign="top">A good caption did the trick here, or it would have just been odd.</td>', 'A good caption did the trick here, or it would have just been odd.', '2007-10-08 23:27:18.000000', NULL, 1),
(4153244, 596225, 83313, '<td valign="top">What did we do before cellphones? A nice touch of humour.</td>', 'What did we do before cellphones? A nice touch of humour.', '2007-10-08 23:28:21.000000', NULL, 1),
(4153245, 596612, 80976, '<td valign="top">The bird appears to be blowing out in several places, also the composition is somewhat lacking.</td>', 'The bird appears to be blowing out in several places, also the composition is somewhat lacking.', '2007-10-08 23:28:28.000000', NULL, 1),
(4153257, 595027, 80976, '<td valign="top">Oh wow, great capture, very nice composition and most of all I love how the boots and net really stand out.</td>', 'Oh wow, great capture, very nice composition and most of all I love how the boots and net really stand out.', '2007-10-08 23:30:52.000000', NULL, 1),
(4153262, 596225, 84124, '<td valign="top">was this done with a single capture?  If so, great shot.</td>', 'was this done with a single capture?  If so, great shot.', '2007-10-08 23:31:42.000000', NULL, 1),
(4153265, 595173, 84124, '<td valign="top">Fantastic idea!  I feel his pain all too much.</td>', 'Fantastic idea!  I feel his pain all too much.', '2007-10-08 23:32:04.000000', NULL, 1),
(4153270, 596912, 80976, '<td valign="top">Sweet.  Leading lines, great color, light, beauty model. Very nice capture.</td>', 'Sweet.  Leading lines, great color, light, beauty model. Very nice capture.', '2007-10-08 23:32:57.000000', NULL, 1),
(4153273, 596921, 84124, '<td valign="top">I imagine you''re quite the patient photographer, well done!</td>', 'I imagine you''re quite the patient photographer, well done!', '2007-10-08 23:33:23.000000', NULL, 1),
