(4153303, 597013, 83313, '<td valign="top">I considered entering one similar in concept, but decided, against it. Your''s is better. It lacks a little impact though. I think if you bumped up the colors a touch, it would have some oomph to it.</td>', 'I considered entering one similar in concept, but decided, against it. Your''s is better. It lacks a little impact though. I think if you bumped up the colors a touch, it would have some oomph to it.', '2007-10-08 23:45:30.000000', NULL, 1),
(4153306, 596630, 83313, '<td valign="top">Creative thinking here.</td>', 'Creative thinking here.', '2007-10-08 23:45:53.000000', NULL, 1),
(4153310, 595655, 83313, '<td valign="top">A little eerie. Good.</td>', 'A little eerie. Good.', '2007-10-08 23:46:19.000000', NULL, 1),
