(4153337, 596845, 83313, '<td valign="top">I''m not finding anything as the subject. My eye just wanders around and does not get steered to anything.</td>', 'I''m not finding anything as the subject. My eye just wanders around and does not get steered to anything.', '2007-10-08 23:52:43.000000', NULL, 1),
(4153341, 596287, 83313, '<td valign="top">I suppose there''s a reason I don''t golf...</td>', 'I suppose there''s a reason I don''t golf...', '2007-10-08 23:53:19.000000', NULL, 1),
(4153343, 596912, 83313, '<td valign="top">Well done, and the caption helps to make the picture.</td>', 'Well done, and the caption helps to make the picture.', '2007-10-08 23:54:02.000000', NULL, 1),
