(4161008, 596886, 77192, '<td valign="top">I hope you didn''t make the girl cry just for the photo. 2 point deduction for being mean ;-)<br/> <br/>the blur and the space around the girl separate her form the background and add to the sense of isolation which tells the story well.</td>', 'I hope you didn''t make the girl cry just for the photo. 2 point deduction for being mean ;-) the blur and the space around the girl separate her form the background and add to the sense of isolation which tells the story well.', '2007-10-11 18:15:52.000000', NULL, 1),
(4161128, 596612, 84440, '<td valign="top">nice details in this shot, but background really competes with the bird. also, the centered composition is really static.</td>', 'nice details in this shot, but background really competes with the bird. also, the centered composition is really static.', '2007-10-11 18:58:51.000000', NULL, 1),
(4161182, 596226, 84440, '<td valign="top">this is very dark on my monitor. I can''t see any detail in the face. I see a pregnant woman holding a birdcage and hand raised as in looking for something. I don''t get the connection. image doesn''t work for me.</td>', 'this is very dark on my monitor. I can''t see any detail in the face. I see a pregnant woman holding a birdcage and hand raised as in looking for something. I don''t get the connection. image doesn''t work for me.', '2007-10-11 19:34:57.000000', NULL, 1),
