(4165198, 596100, 60862, '<td valign="top">Strange things going on with the lighting behind him ...</td>', 'Strange things going on with the lighting behind him ...', '2007-10-13 19:46:37.000000', NULL, 1),
(4165199, 596225, 60862, '<td valign="top">Very fun, well done! :)</td>', 'Very fun, well done! :)', '2007-10-13 19:47:14.000000', NULL, 1),
(4165206, 594835, 60862, '<td valign="top">Beautiful pic of this bird, but not really evoking the concept of "searching" for me other than the title.  I think some more context from pulling back would''ve helped sell the challenge theme.  For example, see the entry "Searching for breakfast."</td>', 'Beautiful pic of this bird, but not really evoking the concept of "searching" for me other than the title.  I think some more context from pulling back would''ve helped sell the challenge theme.  For example, see the entry "Searching for breakfast."', '2007-10-13 19:50:56.000000', NULL, 1),
