INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4165213, 596820, 60862, '<td valign="top">It''s a cute pic, but I don'' see a connection to searching.  Did she drop the top of the snowcone?  If so, a less closeup shot would''ve established the context.</td>', 'It''s a cute pic, but I don'' see a connection to searching.  Did she drop the top of the snowcone?  If so, a less closeup shot would''ve established the context.', '2007-10-13 19:53:17.000000', NULL, 1),
(4165215, 596019, 60862, '<td valign="top">Hahn23, is that you?  I don''t usually give credit for titles, but I''ll do so here, since it''s taught me something, and I''ll take your word this is a searching behavior.</td>', 'Hahn23, is that you?  I don''t usually give credit for titles, but I''ll do so here, since it''s taught me something, and I''ll take your word this is a searching behavior.', '2007-10-13 19:54:40.000000', NULL, 1),
(4165216, 596944, 60862, '<td valign="top">Great facial expressions!</td>', 'Great facial expressions!', '2007-10-13 19:55:17.000000', NULL, 1),
(4165217, 596082, 60862, '<td valign="top">Seems to be resting, not stalking.</td>', 'Seems to be resting, not stalking.', '2007-10-13 19:55:59.000000', NULL, 1),
(4165220, 596612, 60862, '<td valign="top">Like many other bird pics in this challenge, merely shooting an animal doesn''t convey the concept of searching.  Maybe it would''ve worked better with a wider shot showing the what the bird is looking at.</td>', 'Like many other bird pics in this challenge, merely shooting an animal doesn''t convey the concept of searching.  Maybe it would''ve worked better with a wider shot showing the what the bird is looking at.', '2007-10-13 19:57:45.000000', NULL, 1),
(4165221, 596731, 60862, '<td valign="top">Oh, I love minimalist shots like this, where with only a few strokes of light, you convey the subject so well.  Nicely done!</td>', 'Oh, I love minimalist shots like this, where with only a few strokes of light, you convey the subject so well.  Nicely done!', '2007-10-13 19:58:49.000000', NULL, 1),
(4165223, 596836, 60862, '<td valign="top">Fun shot, fun title. I got the idea of asking for directions even without it, but the idea of looking for the past in particular adds a smile to my face. :)</td>', 'Fun shot, fun title. I got the idea of asking for directions even without it, but the idea of looking for the past in particular adds a smile to my face. :)', '2007-10-13 19:59:34.000000', NULL, 1),
(4165224, 596921, 60862, '<td valign="top">Thanks for showing the context of what the bird is doing. So many animal shots in this challenge were basically just portraits.  Here, it''s clear the bird is seeking food.</td>', 'Thanks for showing the context of what the bird is doing. So many animal shots in this challenge were basically just portraits.  Here, it''s clear the bird is seeking food.', '2007-10-13 20:00:16.000000', NULL, 1),
(4165226, 597009, 60862, '<td valign="top">Clever idea!</td>', 'Clever idea!', '2007-10-13 20:01:12.000000', NULL, 1),
(4165227, 596676, 60862, '<td valign="top">Ha!  Nice way to tie this in to the open challenges.</td>', 'Ha!  Nice way to tie this in to the open challenges.', '2007-10-13 20:01:36.000000', NULL, 1),
(4165230, 596554, 60862, '<td valign="top">How does hiding tie into searching?  She doesn''t seem to be looking for him, but rather playing soccer.</td>', 'How does hiding tie into searching?  She doesn''t seem to be looking for him, but rather playing soccer.', '2007-10-13 20:02:05.000000', NULL, 1),
(4165231, 594968, 60862, '<td valign="top">Sorry, I don''t see how this conveys "searching."</td>', 'Sorry, I don''t see how this conveys "searching."', '2007-10-13 20:02:28.000000', NULL, 1),
(4165233, 596590, 60862, '<td valign="top">How is this related to searching?</td>', 'How is this related to searching?', '2007-10-13 20:02:51.000000', NULL, 1),
(4165234, 596789, 60862, '<td valign="top">Sorry, but this is a cute pic of a kid, not a pic that says anything about searching.</td>', 'Sorry, but this is a cute pic of a kid, not a pic that says anything about searching.', '2007-10-13 20:03:15.000000', NULL, 1),
(4165235, 595511, 50695, '<td valign="top">I know you''re getting hit for soft focus and small size, but this is a perfect fulfillment of the challenge and an evocative photo.</td>', 'I know you''re getting hit for soft focus and small size, but this is a perfect fulfillment of the challenge and an evocative photo.', '2007-10-13 20:04:37.000000', NULL, 1),
(4165238, 596877, 60862, '<td valign="top">I often appreciate strong tilts, but this one doesn''t work for me.</td>', 'I often appreciate strong tilts, but this one doesn''t work for me.', '2007-10-13 20:05:42.000000', NULL, 1),
(4165247, 597027, 60862, '<td valign="top">Nice idea, but the harsh lighting and centered composition let you down.</td>', 'Nice idea, but the harsh lighting and centered composition let you down.', '2007-10-13 20:10:50.000000', NULL, 1),
(4165251, 595017, 50695, '<td valign="top">You might get caught in the middle here. Too sentimental for the artsy folks, too soft for the mainstream folks. But I like good storytelling in a photo. High score from me.</td>', 'You might get caught in the middle here. Too sentimental for the artsy folks, too soft for the mainstream folks. But I like good storytelling in a photo. High score from me.', '2007-10-13 20:13:16.000000', NULL, 1),
(4165281, 596756, 77838, '<td valign="top">Very cool lighting on the clouds.</td>', 'Very cool lighting on the clouds.', '2007-10-13 20:33:21.000000', NULL, 1),
(4165287, 597028, 77838, '<td valign="top">Cool, must be a parade of some kind.</td>', 'Cool, must be a parade of some kind.', '2007-10-13 20:34:49.000000', NULL, 1),
(4165291, 596398, 77838, '<td valign="top">Sweet!  I love watching deer.  I also like the grass in the foreground here.</td>', 'Sweet!  I love watching deer.  I also like the grass in the foreground here.', '2007-10-13 20:36:04.000000', NULL, 1),
(4165307, 596630, 1031, '<td valign="top">Nice use of props to create a rebus.</td>', 'Nice use of props to create a rebus.', '2007-10-13 20:42:04.000000', NULL, 1),
(4165312, 596082, 1031, '<td valign="top">Excellent (pre-)action shot.</td>', 'Excellent (pre-)action shot.', '2007-10-13 20:44:27.000000', NULL, 1),
(4165321, 596864, 1031, '<td valign="top">I thought the idea was to play it as it lies ... ;-)</td>', 'I thought the idea was to play it as it lies ... ;-)', '2007-10-13 20:47:09.000000', NULL, 1),
(4165322, 594835, 51538, '<td valign="top">Lovely colours and bokeh. 8.</td>', 'Lovely colours and bokeh. 8.', '2007-10-13 20:47:23.000000', NULL, 1),
(4165324, 596951, 51538, '<td valign="top">I enjoy the juxtaposition, the small private world and the large public urban expanse, the clear the the misty... Nice work. 8.</td>', 'I enjoy the juxtaposition, the small private world and the large public urban expanse, the clear the the misty... Nice work. 8.', '2007-10-13 20:48:03.000000', NULL, 1),
(4165325, 596612, 1031, '<td valign="top">Must be tired of mussels, eh?</td>', 'Must be tired of mussels, eh?', '2007-10-13 20:48:10.000000', NULL, 1),
(4165326, 596839, 51538, '<td valign="top">Interesting geometry and placid subject. 8.</td>', 'Interesting geometry and placid subject. 8.', '2007-10-13 20:48:28.000000', NULL, 1),
(4165328, 595921, 51538, '<td valign="top">Dramatic and interesting horizon line. 8.</td>', 'Dramatic and interesting horizon line. 8.', '2007-10-13 20:49:42.000000', NULL, 1),
(4165330, 596904, 51538, '<td valign="top">The light brings your photo to life. 8.</td>', 'The light brings your photo to life. 8.', '2007-10-13 20:50:14.000000', NULL, 1),
(4165333, 596225, 51538, '<td valign="top">Entertaining photo and the colours are pleasant. 8.</td>', 'Entertaining photo and the colours are pleasant. 8.', '2007-10-13 20:50:36.000000', NULL, 1),
(4165334, 597013, 51538, '<td valign="top">I like the composition and colours, muted as they are. 8.</td>', 'I like the composition and colours, muted as they are. 8.', '2007-10-13 20:51:01.000000', NULL, 1),
(4165336, 596100, 73601, '<td valign="top">nice composition, but the processing throws me</td>', 'nice composition, but the processing throws me', '2007-10-13 20:51:40.000000', NULL, 1),
(4165337, 596772, 73601, '<td valign="top">has a snapshot feel to it, would like to see a more dramatic angle to this</td>', 'has a snapshot feel to it, would like to see a more dramatic angle to this', '2007-10-13 20:52:38.000000', NULL, 1),
(4165338, 595027, 51538, '<td valign="top">Your photo does pose a question - sort of.  But really the answer is that this is a still life composition which suggests searching.  The search could be "why did the photographer compose such a contrived still life?" or "why is such a tiny fisherman using such a huge net?" or, as you said "Where did he go?"  I like the reds and the composition.  8.</td>', 'Your photo does pose a question - sort of.  But really the answer is that this is a still life composition which suggests searching.  The search could be "why did the photographer compose such a contrived still life?" or "why is such a tiny fisherman using such a huge net?" or, as you said "Where did he go?"  I like the reds and the composition.  8.', '2007-10-13 20:53:33.000000', NULL, 1),
(4165339, 596718, 51538, '<td valign="top">Pretty colours and composition.  8.</td>', 'Pretty colours and composition.  8.', '2007-10-13 20:53:53.000000', NULL, 1),
(4165341, 596951, 1031, '<td valign="top">Excellent contrast between "past and future" elements; I like how the treeline roughly lines up with the tops of the buildings to form a diagonal path through the picture. Faded nature of background works well ... going by the image on my monitor, I''d probably experiment with bringing a little more saturation (increase yellows?) into the trees.</td>', 'Excellent contrast between "past and future" elements; I like how the treeline roughly lines up with the tops of the buildings to form a diagonal path through the picture. Faded nature of background works well ... going by the image on my monitor, I''d probably experiment with bringing a little more saturation (increase yellows?) into the trees.', '2007-10-13 20:54:28.000000', NULL, 1),
(4165342, 596781, 73601, '<td valign="top">well good ''rule of thirds'' applied here, just don''t know whats going on in this picture</td>', 'well good ''rule of thirds'' applied here, just don''t know whats going on in this picture', '2007-10-13 20:54:33.000000', NULL, 1),
(4165343, 596463, 51538, '<td valign="top">Lovely interesting point of view. 8.</td>', 'Lovely interesting point of view. 8.', '2007-10-13 20:55:07.000000', NULL, 1),
(4165344, 596567, 51538, '<td valign="top">Nice gilded green there and the theatre is good. 9.</td>', 'Nice gilded green there and the theatre is good. 9.', '2007-10-13 20:55:28.000000', NULL, 1),
(4165345, 596886, 51538, '<td valign="top">Your photo brings a different look at the subject searching.  Nice one. 8.</td>', 'Your photo brings a different look at the subject searching.  Nice one. 8.', '2007-10-13 20:55:56.000000', NULL, 1),
(4165346, 596939, 73601, '<td valign="top">interesting angle for this shot, the guy has a frustrated look to him</td>', 'interesting angle for this shot, the guy has a frustrated look to him', '2007-10-13 20:57:04.000000', NULL, 1),
(4165347, 596590, 73601, '<td valign="top">I don''t see searching here, well composed, but the low light and high iso have left this a bit noisy</td>', 'I don''t see searching here, well composed, but the low light and high iso have left this a bit noisy', '2007-10-13 20:57:10.000000', NULL, 1),
