INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4168257, 596225, 17513, '<td valign="top">well done/congrats</td>', 'well done/congrats', '2007-10-15 03:53:37.000000', NULL, 0),
(4168258, 595921, 17513, '<td valign="top">well done/congrats</td>', 'well done/congrats', '2007-10-15 03:54:07.000000', NULL, 0),
(4168260, 596756, 61552, '<td valign="top">Lucky 13th place!  Good shot!</td>', 'Lucky 13th place!  Good shot!', '2007-10-15 03:54:43.000000', NULL, 0),
(4168262, 596463, 42013, '<td valign="top">Robert...This image looked great as a thumb, I saw it while scanning the entries but didn''t stop to do any voting or commenting. The slight touch of red shirt contrasts nicely with the green corn, then the nets full of clams(?) have just enough detail to set the scene off nicely. The steam... perfect, I could go on but I don''t want to give you a big head. ;) <br/> <br/>It truly shows the searchers, looking for the perfect take home item. Glad you did so well.</td>', 'Robert...This image looked great as a thumb, I saw it while scanning the entries but didn''t stop to do any voting or commenting. The slight touch of red shirt contrasts nicely with the green corn, then the nets full of clams(?) have just enough detail to set the scene off nicely. The steam... perfect, I could go on but I don''t want to give you a big head. ;)  It truly shows the searchers, looking for the perfect take home item. Glad you did so well.', '2007-10-15 03:55:36.000000', NULL, 0),
(4168264, 595921, 42013, '<td valign="top">Nice work Tate. Curious how you held the detail in the sky and the foreground?</td>', 'Nice work Tate. Curious how you held the detail in the sky and the foreground?', '2007-10-15 03:58:39.000000', NULL, 0),
(4168268, 596225, 49109, '<td valign="top">Congrats on your ribbon, this was my favorite (even over my entry), great idea and execution!</td>', 'Congrats on your ribbon, this was my favorite (even over my entry), great idea and execution!', '2007-10-15 04:03:04.000000', NULL, 0),
(4168272, 595921, 49109, '<td valign="top">Congrats on your ribbon, excellent work!</td>', 'Congrats on your ribbon, excellent work!', '2007-10-15 04:04:09.000000', NULL, 0),
(4168274, 596463, 43073, '<td valign="top">So many perfect elements here, the flashes of light and color, the naturally monotone-ish areas in the lower center/left, the off-kilter horizon, the people "appearing" out of the steam, and all of it fading so perfectly into that patch of blue and cloud at the top-left. Congrats on a great finish for a great shot, I wouldn''t change a thing.</td>', 'So many perfect elements here, the flashes of light and color, the naturally monotone-ish areas in the lower center/left, the off-kilter horizon, the people "appearing" out of the steam, and all of it fading so perfectly into that patch of blue and cloud at the top-left. Congrats on a great finish for a great shot, I wouldn''t change a thing.', '2007-10-15 04:05:32.000000', NULL, 0),
(4168279, 596718, 49109, '<td valign="top">Congrats on your 5th, Mark. Not as shoehorned as you thought (compared to about half of the competition).</td>', 'Congrats on your 5th, Mark. Not as shoehorned as you thought (compared to about half of the competition).', '2007-10-15 04:12:13.000000', NULL, 0),
